import{_ as s,o as a,c as i,a3 as t}from"./chunks/framework.CWpttWmj.js";const k=JSON.parse('{"title":"Marketplace","description":"","frontmatter":{},"headers":[],"relativePath":"guide/marketplace.md","filePath":"guide/marketplace.md","lastUpdated":1785888355000}'),n={name:"guide/marketplace.md"};function r(l,e,h,o,p,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="marketplace" tabindex="-1">Marketplace <a class="header-anchor" href="#marketplace" aria-label="Permalink to &quot;Marketplace&quot;">​</a></h1><p>The marketplace lets an owner list a <code>.arc</code> name for sale and a buyer purchase it in a single atomic transaction. There is no escrow — the name stays in the seller&#39;s wallet until it sells.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  Seller                                Market                        Buyer</span></span>
<span class="line"><span>    │                                     │                             │</span></span>
<span class="line"><span>    │ 1. approve(market, tokenId)         │                             │</span></span>
<span class="line"><span>    ├────────────────────────────────────►│                             │</span></span>
<span class="line"><span>    │ 2. list(tokenId, price)             │                             │</span></span>
<span class="line"><span>    ├────────────────────────────────────►│                             │</span></span>
<span class="line"><span>    │                                     │◄──── 3. buy(id, maxPrice) ──┤</span></span>
<span class="line"><span>    │◄──── price − fee ───────────────────┤                             │</span></span>
<span class="line"><span>    │                                     ├──── token ─────────────────►│</span></span></code></pre></div><p>The name never leaves the seller&#39;s custody. The market holds an <strong>approval</strong>, not the token, and uses it to transfer at the moment of sale. If the seller revokes the approval or transfers the name away, the listing simply stops being fillable.</p><h2 id="listing-a-name" tabindex="-1">Listing a name <a class="header-anchor" href="#listing-a-name" aria-label="Permalink to &quot;Listing a name&quot;">​</a></h2><p>Two transactions, because the approval must come first.</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">approve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(market, tokenId)      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// on the registrar</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(tokenId, price)          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// on the market</span></span></code></pre></div><p>The market checks both when you list:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;price&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(registrar.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ownerOf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(id) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;!owner&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">_approved</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(id, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;!approved&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>In the app: <strong>My names → the name → List for sale</strong>. It handles the approval step for you and disables the button until the approval confirms.</p><p>A price of zero is rejected — use <code>unlist</code> to withdraw a listing instead.</p><div class="warning custom-block"><p class="custom-block-title">You cannot list a name that has expired</p><p><code>ownerOf</code> reverts with <code>expired</code> past the expiry, including during the grace period, so listing fails. <a href="/docs/guide/renewals.html">Renew first</a>, then list.</p></div><h3 id="changing-the-price" tabindex="-1">Changing the price <a class="header-anchor" href="#changing-the-price" aria-label="Permalink to &quot;Changing the price&quot;">​</a></h3><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setPrice</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(tokenId, newPrice)</span></span></code></pre></div><p>Only the original lister can call it — the market checks <code>l.seller == msg.sender</code> and reverts with <code>!seller</code> otherwise. One transaction, no re-approval needed.</p><h3 id="removing-a-listing" tabindex="-1">Removing a listing <a class="header-anchor" href="#removing-a-listing" aria-label="Permalink to &quot;Removing a listing&quot;">​</a></h3><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unlist</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(tokenId)</span></span></code></pre></div><p>Same restriction — the seller only. Revoking the ERC-721 approval also makes a listing unfillable, but it leaves the listing visible in the UI, so <code>unlist</code> is the clean way to withdraw.</p><h2 id="buying-a-name" tabindex="-1">Buying a name <a class="header-anchor" href="#buying-a-name" aria-label="Permalink to &quot;Buying a name&quot;">​</a></h2><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">buy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> maxPrice) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">payable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">buy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">payable</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                            // maxPrice = msg.value</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">buy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> maxPrice, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> referrer) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">payable</span></span></code></pre></div><p>Settlement is atomic: the token transfers to you and the proceeds go to the seller in the same transaction. Either both happen or neither does.</p><h3 id="maxprice-protects-you" tabindex="-1">maxPrice protects you <a class="header-anchor" href="#maxprice-protects-you" aria-label="Permalink to &quot;maxPrice protects you&quot;">​</a></h3><p><code>buy</code> takes a <code>maxPrice</code> and reverts with <code>price moved</code> if the listing costs more:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(l.price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> maxPrice, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;price moved&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>This is your defence against a seller front-running your purchase with a <code>setPrice</code> that raises the price just as you buy. The app sets <code>maxPrice</code> to the price you were shown.</p><div class="danger custom-block"><p class="custom-block-title">The one-argument buy() has no price protection</p><p><code>buy(id)</code> sets <code>maxPrice</code> to <code>msg.value</code> — whatever you sent. If the seller raises the price to just under your balance between your quote and your transaction, you pay it.</p><p>Always use <code>buy(id, maxPrice)</code> with an explicit maximum. This is the form the app uses.</p></div><h3 id="other-checks-at-purchase-time" tabindex="-1">Other checks at purchase time <a class="header-anchor" href="#other-checks-at-purchase-time" aria-label="Permalink to &quot;Other checks at purchase time&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Check</th><th>Revert</th><th>Meaning</th></tr></thead><tbody><tr><td>Listing exists</td><td><code>!listed</code></td><td>Not listed, or already sold/unlisted.</td></tr><tr><td>Native currency</td><td><code>usdc listing</code></td><td>The listing settles in ERC-20 USDC; use the USDC purchase path.</td></tr><tr><td>Seller still owns it</td><td><code>seller changed</code></td><td>The seller transferred the name after listing. The listing is stale.</td></tr><tr><td>Enough sent</td><td><code>underpaid</code></td><td><code>msg.value</code> below the amount due.</td></tr></tbody></table><p>Overpayment is refunded in the same transaction.</p><h2 id="what-the-sale-does-to-the-name" tabindex="-1">What the sale does to the name <a class="header-anchor" href="#what-the-sale-does-to-the-name" aria-label="Permalink to &quot;What the sale does to the name&quot;">​</a></h2><p>On settlement the market transfers the token <strong>and</strong> fixes up the registry side, so a bought name isn&#39;t left in the half-transferred state a raw <code>transferFrom</code> produces. Even so, after buying you should:</p><ol><li>Verify <code>registry.owner(node)</code> is you — and call <code>reclaim</code> if it isn&#39;t.</li><li><strong>Update the address record.</strong> The name may still resolve to the seller until you call <code>setAddr</code>. Anyone paying the name before you do pays them.</li></ol><p>See <a href="/docs/guide/claiming.html#after-you-claim-a-name">Claiming a name → after you claim</a>.</p><h2 id="fees" tabindex="-1">Fees <a class="header-anchor" href="#fees" aria-label="Permalink to &quot;Fees&quot;">​</a></h2><p>The market takes a fee in basis points, deducted from the seller&#39;s proceeds:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>buyer pays   price</span></span>
<span class="line"><span>seller gets  price − (price × feeBps / 10000)</span></span></code></pre></div><p><code>feeBps</code> is set by the contract owner and <strong>initialises to zero</strong>, so unless it has been changed the seller receives the full price. It is a live on-chain value — read <code>feeBps()</code> rather than trusting a number written in docs. See <a href="/docs/protocol/fees.html#marketplace-fees">Fees</a>.</p><p>If paying the seller fails, the amount is credited to a pending balance they can withdraw later rather than reverting the sale.</p><h2 id="referrals" tabindex="-1">Referrals <a class="header-anchor" href="#referrals" aria-label="Permalink to &quot;Referrals&quot;">​</a></h2><p>The marketplace has its own referral system, independent of the one in the controller. Supplying a referrer to <code>buy</code> can grant the buyer a discount and pay the referrer a reward, both in basis points, both defaulting to zero.</p><p>The two rates together can never exceed the market fee:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(discountBps </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rewardBps </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> feeBps, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;exceeds fee&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>So referrals are funded out of the protocol&#39;s own fee, never out of the seller&#39;s proceeds. With <code>feeBps</code> at zero, market referrals are necessarily inert.</p><p>Sales emit <code>ReferralPaid(id, referrer, referee, reward)</code>.</p><div class="info custom-block"><p class="custom-block-title">Not yet wired into the app</p><p>The referral parameter exists in the deployed market but the app calls <code>buy</code> without it. Integrators can use it today.</p></div><h2 id="currencies" tabindex="-1">Currencies <a class="header-anchor" href="#currencies" aria-label="Permalink to &quot;Currencies&quot;">​</a></h2><p>Listings carry a currency flag: <code>0</code> for the native token, <code>1</code> for ERC-20 USDC. The two are not interchangeable — calling native <code>buy</code> on a USDC listing reverts with <code>usdc listing</code>.</p><p>The app currently lists and buys in the <strong>native</strong> token only. USDC listings appear in API results with <code>currency: 1</code>; filter them out if your integration only handles native settlement. See <a href="/docs/protocol/fees.html#two-kinds-of-usdc">Fees → two kinds of USDC</a>.</p><h2 id="browsing-listings" tabindex="-1">Browsing listings <a class="header-anchor" href="#browsing-listings" aria-label="Permalink to &quot;Browsing listings&quot;">​</a></h2><p>In the app: the <strong>Marketplace</strong> tab, showing active listings with prices and expiry dates.</p><p>Over the API, cursor-paginated:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/marketplace?limit=50</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/v1/marketplace?limit=50&amp;cursor=&lt;nextCursor&gt;</span></span></code></pre></div><p>Default <code>limit</code> is 50, maximum 200. See <a href="/docs/api/endpoints.html#marketplace">API endpoints</a>.</p><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Listed(id, seller, price)</code></td><td>New listing.</td></tr><tr><td><code>PriceChanged(id, seller, price)</code></td><td>Price updated.</td></tr><tr><td><code>Unlisted(id, seller)</code></td><td>Listing withdrawn.</td></tr><tr><td><code>Sold(id, seller, buyer, price, fee)</code></td><td>Sale settled.</td></tr><tr><td><code>ReferralPaid(id, referrer, referee, reward)</code></td><td>Referral reward paid.</td></tr></tbody></table><h2 id="before-you-buy" tabindex="-1">Before you buy <a class="header-anchor" href="#before-you-buy" aria-label="Permalink to &quot;Before you buy&quot;">​</a></h2><ul><li><strong>Check the expiry.</strong> A cheap name with two weeks left needs renewing immediately.</li><li><strong>Check the name&#39;s characters.</strong> Listings can contain names the app would never let you type, including look-alikes for well-known names. See <a href="/docs/safety.html#look-alike-names">Safety</a>.</li><li><strong>Use an explicit <code>maxPrice</code>.</strong></li><li><strong>Never pay outside an atomic transaction.</strong> See <a href="/docs/safety.html#buying-a-name-safely">Safety</a>.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/docs/guide/ownership.html">Ownership &amp; transfers</a> — approvals and reclaim.</li><li><a href="/docs/protocol/fees.html">Fees</a> — the full fee picture.</li><li><a href="/docs/safety.html">Safety</a> — marketplace-specific risks.</li></ul>`,60)])])}const g=s(n,[["render",r]]);export{k as __pageData,g as default};
